//! __NAME__: a barq routing strategy.
//!
//! Generated by `contrib/new_strategy.py`. A strategy receives a
//! [`RouteInput`] (who pays whom, how much, our channels, channels to
//! avoid) and returns an LDK [`Path`]. Each hop's `fee_msat` is what that
//! hop's node receives on top of what it forwards (the last hop's is the
//! amount delivered), and `cltv_expiry_delta` is the delta it adds (the
//! last hop's is the final CLTV delta).
//!
//! To make barq use it, add a variant to `StrategyKind` and build it in
//! `build_strategy` (barq-plugin/src/methods/pay.rs).
use anyhow::Result;

use crate::ldk::ln::features::{ChannelFeatures, NodeFeatures};
use crate::ldk::routing::router::{Path, RouteHop};
use crate::strategy::{Payee, RouteInput, RouteOutput, Strategy};

#[derive(Default)]
pub struct __TYPE__;

impl Strategy for __TYPE__ {
    fn can_apply(&self, input: &RouteInput) -> Result<bool> {
        // TODO: decide when this strategy is worth trying.
        Ok(matches!(input.payee, Payee::Clear { .. }) && !input.first_hops.is_empty())
    }

    fn route(&self, input: &RouteInput) -> Result<RouteOutput> {
        // TODO: replace with your algorithm. This placeholder pays the
        // destination when it is one of our peers.
        let Some(destination) = input.payee.node_id() else {
            anyhow::bail!("__NAME__ cannot pay a blinded path");
        };
        let Some(channel) = input.first_hops.iter().find(|hop| {
            hop.peer_id == destination
                && hop.spendable_msat >= input.amount_msat
                && !input.excluded_channels.contains(&hop.scid)
        }) else {
            anyhow::bail!("__NAME__ found no route");
        };
        Ok(RouteOutput {
            path: Path {
                hops: vec![RouteHop {
                    pubkey: destination,
                    node_features: NodeFeatures::empty(),
                    short_channel_id: channel.scid,
                    channel_features: ChannelFeatures::empty(),
                    fee_msat: input.amount_msat,
                    cltv_expiry_delta: input.final_cltv_delta,
                    maybe_announced_channel: channel.is_public,
                }],
                blinded_tail: None,
            },
        })
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::simulation::{Policy, SimulatedNetwork};

    #[test]
    fn __MODULE___routes_to_a_peer() {
        let net = SimulatedNetwork::line(3, 1_000_000, Policy::default()).unwrap();
        let strategy = __TYPE__;
        let input = net.route_input(0, 1, 10_000);
        assert!(strategy.can_apply(&input).unwrap());
        let route = strategy.route(&input).unwrap();
        assert_eq!(route.path.hops.last().unwrap().pubkey, net.node_id(1));
        assert_eq!(route.path.hops.last().unwrap().fee_msat, 10_000);
    }
}
